def _transition(state, d, s_max):
    started = (state >> 10) & 1
    s = state >> _STATE_BITS
    if started:
        ns = s + d
        if ns > s_max:
            return -1
        if d == 0 or (state >> 9) & 1:
            return (ns << _STATE_BITS) | (1 << 10) | (1 << 9)
        return ((ns << _STATE_BITS) | (1 << 10)
