from functools import lru_cache
from math import comb

MOD = 10**9 + 7

def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    def digit_count(n, d):
        return (n // (10 ** d)) % 10

    def digit_sum(n, d):
        return (n // (10 ** d)) % 10

    def count(n, d, sum_, tight):
        if d == -1:
            return 1 if sum_ >= min_sum and sum_ <= max_sum else 0
        res = 0
        limit = 9 if not tight else digit_count(n, d)
        for i in range(limit + 1):
            res += count(n, d - 1, sum_ + i, tight and i == limit)
        return res % MOD

    def count_upto(n):
        return count(n, len(n) - 1, 0, True)

    return (count_upto(num2) - count_upto(num1 - 1) + (1 if int(num1) >= min_sum else 0)) % MOD
```

