    L1, C1, K1 = sensor1
    L2, C2, K2 = sensor2
    K1 = max(int(K1), 0)
    K2 = max(int(K2), 0)

    dp = {0: 0}

    for d in sections:
        max_i = _ceil_div(d, L1) if L1 > 0 else 0
        if max_i > K1:
            max_i = K1

        ndp = {}
        for used1, used2 in dp.items():
            for i in range(max_i + 1):
                total1 = used1 + i
                if total1 > K1:
                    break
                remainder = d - i * L1 if L1 > 0 else d
                if remainder <= 0:
                    j = 0
                elif L2 > 0:
                    j = _ceil_div(remainder, L2)
                else:
                    continue
                total2 = used2 + j
                if total2 > K2:
                    continue
                current = ndp.get(total1)
                if current is None or total2 < current:
                    ndp[total1] = total2
        dp = ndp
        if not dp:
            return -1

    best = None
    for i, j in dp.items():
        cost = C1 * i + C2 * j
        if best is None or cost < best:
            best = cost
    return -1 if best is None else best
