        for x in code:
            deg[x] += 1

        total = 0
        valid = True

        for x in code:
            leaf = 0
            while deg[leaf] != 1 and leaf < n:
                leaf += 1

            w = weight[x][leaf]
            if w < 0:
                valid = False
                break

            total += w
            deg[x] -= 1
            deg[leaf] -= 1

        if not valid:
            continue

        first = -1
        second = -1
        for v in range(n):
            if deg[v] == 1:
