def min_absolute_difference(nums: List[int], k: int) -> int:
    ans = 10**30
    prev_or = set()
    for x in nums:
        cur_or = {x}
        for val in prev_or:
            cur_or.add(val | x)
        for val in cur_or:
            diff = abs(k - val)
            if diff < ans:
                ans = diff
                if ans == 1:
                    return 0
        prev_or = cur_or
