def can_reach_end(n: int, m: int, a: int, b: int, bad_intervals: List[Tuple[int, int]]) -> bool:
    if n <= 1:
        return True

    cleaned = []
    for interval in (bad_intervals or []):
        try:
            l, r = interval
        except Exception:
            continue
        if l > r:
            continue
        l = max(1, int(l))
        r = min(n, int(r))
        if l > r:
            continue
        cleaned.append((l, r))
    cleaned.sort()

    blocks = []
    for l, r in cleaned:
        if blocks and l <= blocks[-1][1] + 1:
            if r > blocks[-1][1]:
                blocks[-1][1] = r
        else:
            blocks.append([l, r])

    if not blocks:
        return False

    if blocks[-1][1] != n:
        return False

    proc_start = []
    proc = []

    def stretch_query(st, p):
        d = p - st[0]
        length = st[1] - st[0]
        if d < 0 or d > length:
            return False
        kind = st[2]
        if kind == 0:
            sparse, contig_q = st[3]
            if contig_q is not None and d >= contig_q:
                return True
            return d in sparse
        else:
            residues = st[3]
            r = d % st[4]
            mind = residues.get(r)
            return mind is not None and d >= mind

    def reach(p):
        if p < 1:
            return False
        if p == 1:
            return True
        i = bisect_right(proc_start, p) - 1
        if i < 0:
            return False
        st = proc[i]
        if p > st[1]:
            return False
        return stretch_query(st, p)

    if b > a:
        j0 = -(-(a - 1) // (b - a))
        contig_bound = j0 * a
    else:
        contig_bound = 0
    CUT = max(2 * b, contig_bound + 2 * b + 40)

    for (L, R) in cleaned:
        length = R - L
        win = {}
        for x in range(max(1, L - b), L):
            win[x] = reach(x)
        entries = set()
        for x, ok in win.items():
            if not ok:
                continue
            lo = max(a, L - x)
            hi = min(b, R - x)
            for i in range(lo, hi + 1):
                entries.add(x + i - L)
        if L == 1:
            entries.add(0)

        if not entries:
            st = (L, R, 0, (set(), None), 0)
            proc_start.append(L)
            proc.append(st)
            continue

        if b > a:
            limit = min(length, CUT)
            f = set()
            contig_q = None
            d = 0
            while d <= limit:
                if d in entries:
                    f.add(d)
                else:
                    ok = False
                    hi = min(b, d)
                    for i in range(a, hi + 1):
                        if (d - i) in f:
                            ok = True
                            break
                    if not ok:
                        for i in range(max(a, d + 1), b + 1):
                            if win.get(L + d - i, False):
                                ok = True
                                break
                    if ok:
                        f.add(d)
                if d >= a - 1:
                    q = d - a + 1
                    all_in = True
                    for j in range(a):
                        if (d - j) not in f:
                            all_in = False
                            break
                    if all_in:
                        contig_q = q
                        break
                d += 1
            if contig_q is None and f and length > limit:
                base = min(f)
                contig_q = base + contig_bound
            if contig_q is not None:
                sparse = {d for d in f if d < contig_q}
            else:
                sparse = set(f)
            st = (L, R, 0, (sparse, contig_q), 0)
        else:
            k = a
            residues = {}
            for e in entries:
                r = e % k
                if r not in residues or e < residues[r]:
                    residues[r] = e
            st = (L, R, 1, residues, k)

        proc_start.append(L)
        proc.append(st)

    last = proc[-1]
    return stretch_query(last, n)
