from typing import List

def paint_walls(cost: List[int], time: List[int]) -> int:
    n = len(cost)
    INF = 10**30
    dp = {}

    def dfs(i, w):
        if i == n:
            return 0
        if (i, w) in dp:
            return dp[(i, w)]
        prev = i - w
        if prev < 0:
            prev = 0
        dp[(i, w)] = min(dfs(i + 1, w), dfs(prev, w - 1) + cost[i])
        return dp[(i, w)]

