def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    vals = tuple(cell for row in grid for cell in row)
    @lru_cache(maxsize=None)
    def takahashi_wins(state: tuple) -> bool:
        red_sum = sum(vals[i] for i in range(9) if state[i] == 1)
        blue_sum = sum(vals[i] for i in range(9) if state[i] == 2)
        n_red = state.count(1)
        n_blue = state.count(2)
        whites = [i for i in range(9) if state[i] == 0]
        for a, b, c in _LINES:
            if state[a] != 0 and state[a] == state[b] == state[c]:
                return state[a] == 1
        if not whites:
            return red_sum > blue_sum
        if n_red == n_blue:
            for m in whites:
                child = state[:m] + (1,) + state[m + 1:]
                if takahashi_wins(child):
                    return True
            return False
        else:
            for m in whites:
                child = state[:m] + (2,) + state[m + 1:]
                if not takahashi_wins(child):
                    return False
            return True
    return 'Takahashi' if takahashi_wins((0,) * 9) else 'Aoki'
