from typing import List

def paint_walls(cost: List[int], time: List[int]) -> int:
    n = len(cost)
    INF = 10**30
    dp = [INF] * (n + 1)
    dp[0] = 0
    memo = {}

    for c, t in zip(cost, time):
        w = t + 1
        for j in range(n, 0, -1):
            prev = j - w
            if prev < 0:
                prev = 0
            if (j, prev) not in memo:
                if dp[prev] + c < dp[j]:
                    dp[j] = dp[prev] + c
                    memo[(j, prev)] = dp[j]
            else:
                if memo[(j, prev)] + c < dp[j]:
                    dp[j] = memo[(j, prev)] + c

    return dp[n]
