        if not entries:
            st = (L, R, 0, (set(), None), 0)
            proc_start.append(L)
            proc.append(st)
            continue

        if b > a:
            # DP over offsets 0..min(length, CUT).  As soon as `a` consecutive
            # reachable offsets appear (guaranteed to happen by offset
            # <entry_offset> + j0*a + a - 1 when the stretch is long enough), every
            # good square from there up to R is reachable (jump by `a`).
            limit = min(length, CUT)
            f = set()
            contig_q = None
            d = 0
            while d < limit:
                if d in entries:
                    f.add(d)
                else:
                    ok = False
                    hi = min(b, d)
                    for i in range(a, hi + 1):
                        if (d - i) in f:
                            ok = True
                            break
                    if not ok:
                        for i in range(max(a, d + 1), b + 1):
                            if win.get(L + d - i, False):
                                ok = True
                                break
                    if ok:
                        f.add(d)
                if d >= a - 1:
                    q = d - a + 1
                    all_in = True
                    for j in range(a):
                        if (d - j) not in f:
                            all_in = False
                            break
                    if all_in:
                        contig_q = q
                        break
                d += 1
            if contig_q is None and f and length > limit:
                # Safety net (mathematically unreachable): fall back to the proven contiguous frontier of the earliest reachable offset.
                base = min(f)
                contig_q = base + contig_bound
            if contig_q is not None:
                sparse = {d for d in f if d < contig_q}
            else:
                sparse = set(f)
            st = (L, R, 0, (sparse, contig_q), 0)
        else:
            # a == b == k: square L + d is reachable iff some entry offset e with e <= d and e == d (mod k) exists.
            k = a
            residues = {}
            for e in entries:
                r = e % k
                if r not in residues or e < residues[r]:
                    residues[r] = e
            st = (L, R, 1, residues, k)

        proc_start.append(L)
        proc.append(st)

    # ---- Answer: is n reachable? (n is the last square of the last stretch.) --
    last = proc[-1]
    return stretch_query(last, n)
